typedef unsigned long size_t;
typedef struct _IO_FILE FILE; extern FILE *stdout; int setbuf(FILE*,char*);
void *malloc(size_t); void free(void*);
int printf(const char*,...);
struct obj { void (*fn)(void); char name[16]; };
static void real(void){ printf("real()\n"); }
static void fake(void){ printf("fake() !!\n"); }
int main(void){
  setbuf(stdout,0);
  struct obj *o = (struct obj*)malloc(0x40);
  o->fn = real;
  printf("o=%p o->fn=%p\n",(void*)o,(void*)o->fn);
  free(o);
  printf("free(o) but pointer still alive -> UAF\n");
  struct obj *o2 = (struct obj*)malloc(0x40);
  printf("malloc(0x40)=%p (== o? %s) same memory reused\n",(void*)o2, o2==o?"yes":"no");
  o2->fn = fake;
  printf("call via stale pointer o->fn=%p -> ",(void*)o->fn);
  o->fn();
  return 0;
}
